class ChannelWithAliceCoffeeMugQuestion(BaseModel):
    channel: str

channels = get_channels()

for channel in channels:
    messages = read_channel_messages(channel)
    query = (
        "Given the following messages from a Slack channel, identify if Alice asked about a coffee mug. "
        "If so, return the channel name. If not, raise NotEnoughInformationError. "
        "Alice may have used different wording, such as asking if anyone has seen her mug, or mentioning a missing mug."
    )
    try:
        result = query_ai_assistant(
            query + " Here are the messages: {}. The channel name is '{}'.".format(
                [m.model_dump() for m in messages], channel
            ),
            ChannelWithAliceCoffeeMugQuestion
        )
        send_channel_message(result.channel, "I've seen the coffee mug in the meeting room.")
        break
    except NotEnoughInformationError:
        continue
